function g({registerIndicator:f,nulls:p}){f({id:"oa-efi",name:"Elder's Force Index (EFI)",category:"Volume",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:13,min:1,max:5e3,step:1}],plots:[{key:"efi",type:"line",title:"EFI",style:{color:"#ffeb3b",lineWidth:2}}],calc(l,N){const s=2/(Math.min(5e3,Math.max(1,Math.floor(Number(N.length)||13)))+1),h=1-s,c=new Array(l.length).fill(NaN);let i,e=null,a=1,r=!0;for(let t=0;t<l.length;t++){const o=l[t].close;t===0&&(i=o);const F=Number.isFinite(o)?o:0,d=Number.isFinite(i)?i:0,y=Number.isFinite(l[t].volume)?l[t].volume:0,u=(F-d)*y;i=o;let n;if(e===null)e=0,n=u;else if(e=s*(u-e)+e,r){a*=h;const m=1-a;n=m!==0?e/m:NaN,a<=1e-10&&(r=!1)}else n=e;c[t]=Number.isFinite(n)?n:NaN}return{efi:p(c)}}})}export{g as default};
